p = 'src/status.rs'
s = open(p).read()
old = """    /// Reserves the next unused index, or `None` once the list is full.
    pub fn allocate(&mut self) -> Option<usize> {
        if self.allocated >= self.capacity {
            return None;
        }
        self.allocated += 1;
        Some(self.allocated)
    }"""
new = """    /// Reserves the next unused index, or `None` once the list is full.
    ///
    /// Indexes run from 1 (the numbering already in issued credentials). The
    /// last one would fall past the end of the bitstring, so it takes bit 0,
    /// which nothing else uses.
    pub fn allocate(&mut self) -> Option<usize> {
        if self.allocated >= self.capacity {
            return None;
        }
        self.allocated += 1;
        Some(self.allocated % self.capacity)
    }"""
assert old in s
open(p, 'w').write(s.replace(old, new))
EOF
git diff src/status.rs; echo "===== GREEN"; RUST_BACKTRACE=0 cargo test --offline --test status 2>&1 | grep -E "^test |test result"

